
@forelse($records as $ticket)<tr><td><a href="{{ route('dashboard.tickets.show', $ticket->id) }}">#{{ $ticket->id }}</a></td><td>{{ optional($ticket->employee)->name ?? 'Unavailable requester' }}<small>{{ optional($ticket->employee)->email }}</small></td><td>{{ optional(optional($ticket->employee)->department)->name ?? 'Not specified' }}</td><td>{{ optional($ticket->task)->name }}<small>{{ Str::limit($ticket->support_specifics, 100) }}</small></td><td><span class="dashboard-status" data-status="{{ $ticket->status }}">{{ $ticket->status }}</span></td><td>{{ optional($ticket->technician)->name ?? 'Unassigned' }}</td><td>{{ optional($ticket->created_at)->format('M d, Y') }}<small>{{ optional($ticket->created_at)->format('h:i A') }}</small></td><td><a href="{{ route('dashboard.tickets.show', $ticket->id) }}" class="btn btn-secondary btn-sm icon-action" aria-label="Manage ticket {{ $ticket->id }}"><x-action-icon name="pencil-square" /></a></td></tr>@empty @unless($datatable ?? false)<tr><td colspan="8" class="empty-cell">No support tickets match your filters.</td></tr>@endunless @endforelse

